def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    background = max(colors, key=lambda color: sum(row.count(color) for row in grid))
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    for sr, sc, step in ((r, c, -1), (nr, nc, 1)):
                        rr, cc = sr + step * dr, sc + step * dc
                        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                            out[rr][cc] = color
                            rr += step * dr
                            cc += step * dc

    return out
